function tesla(c,t,mode){const s=phaseInfo('tesla',t,mode),p=ease(s.progress),xs=[100,300,500,700];line(c,[[75,265],[727,265]],'#7d8992',13);for(let i=0;i<4;i++){node(c,xs[i]-80,75,160,65,['FASTEN','TORQUE LOG','EOL CHECK','MES RECORD'][i],null,s.index===i);line(c,[[xs[i],141],[xs[i],226]],C.line,2,[4,5]);}const x=s.index===0?100:lerp(xs[s.index-1],xs[s.index],p);rect(c,x-32,237,64,39,'#a8b5bc',5);for(let j=0;j<3;j++)rect(c,x-23+j*17,245,12,22,'#424e56',2);const gaugeX=230,gaugeW=145;rect(c,gaugeX,176,gaugeW,12,'#48575e',2);rect(c,gaugeX+48,176,50,12,'#789d88',2);let marker=mode==='variation'?gaugeX+128:gaugeX+73;line(c,[[marker,168],[marker,196]],mode==='variation'?C.orange:C.white,3);text(c,'Illustrative tolerance band',300,217,14,C.muted,'center');if(s.index>=2){const bad=mode==='variation';circle(c,500,165,9,bad?C.orange:C.green);text(c,bad?'FLAG':'PASS',520,171,16,bad?C.orange:C.green);if(bad){line(c,[[500,275],[500,326],[390,326]],C.orange,2,[5,5]);text(c,'Trace fastening variation',498,357,17,C.orange,'center');}}text(c,mode==='variation'?'One failure cycle: log → flag → trace the source':'One controlled cycle: fasten → validate → record',400,398,17,C.white,'center');}
