function npi(c,t,mode){const s=phaseInfo('npi',t,mode);const shared=mode==='shared';const names=['RF','Audio','Memory','Display','Power','Camera','Sensors','Connectivity'];for(let i=0;i<8;i++){let x=30+(i%2)*130,y=50+Math.floor(i/2)*80;node(c,x,y,116,49,names[i],null,Math.floor(t/3)%8===i);const p=[[x+116,y+24],[310,y+24],[310,208],[353,208]];line(c,p,shared?'#526776':'#52595e',1,shared?[]:[3,6]);if(Math.floor(t/3)%8===i){const pos=pathPoint(p,(t%3)/3);item(c,...pos,'',C.orange,12);}}if(shared){const labels=['CALIBRATE','ISOLATE','QUALIFY'];for(let i=0;i<3;i++){node(c,352+i*137,168,120,80,labels[i],null,s.index===i+1);if(i<2)line(c,[[472+i*137,208],[489+i*137,208]],C.orange,2);}if(s.index>=1){const xp=lerp(356+(s.index-1)*137,456+(s.index-1)*137,ease(s.progress));item(c,xp,266,'',C.orange,13);}text(c,'One shared validation sequence',555,315,18,C.white,'center');}else{for(let i=0;i<4;i++){node(c,360,53+i*80,363,49,['Procedure A','Procedure B','Procedure C','Procedure D'][i],'',Math.floor(t/3)%4===i);}text(c,'Subsystem-specific procedures',543,400,18,C.orange,'center');}}
function stretch(c,t,mode){const s=phaseInfo('stretch',t,mode),p=ease(s.progress);rect(c,35,72,220,235,'#364249',4);text(c,'TRAILER',144,54,17,C.white,'center');for(let x=60;x<220;x+=51)for(let y=128;y<275;y+=51)rect(c,x,y,39,39,'#ab735b',3);line(c,[[463,308],[756,308]],'#89979f',14);for(let x=471;x<750;x+=27)line(c,[[x,300],[x,317]],'#4d5b64',3);rect(c,340,291,67,24,'#91a2ac',4);let from,to;if(s.index===0){from=[369,168];to=[224,197];}else if(s.index===1){from=[224,197];to=[275,147];}else if(s.index===2){from=[275,147];to=[523,268];}else{from=[523,268];to=[369,168];}let target=[lerp(from[0],to[0],p),lerp(from[1],to[1],p)];if(mode==='blocked'&&s.index>=2)target=[420,170];arm(c,[373,290],target,120,140);if(s.index===1||s.index===2){if(mode==='grip'){item(c,224,lerp(208,278,p),'',C.orange,28);}else item(c,target[0],target[1]+24,'',C.orange,28);}if(s.index===3&&mode!=='grip')item(c,mode==='blocked'?553:lerp(553,742,p),285,'',C.orange,26);if(mode==='blocked'){rect(c,686,265,9,36,C.orange);text(c,'HOLD',690,247,17,C.orange,'center');}let message=mode==='grip'?'Grip lost · carton not transferred':mode==='blocked'?'Conveyor blocked · unload transfer waits':s.label;let color=mode==='normal'?C.white:C.orange;text(c,message,400,378,19,color,'center');text(c,'Representative robot geometry · no vendor kinematic model',400,415,14,C.muted,'center');}
const renderers={cobot,tesla,slotting,layout,npi,stretch};
const descriptions={cobot:'Watch the device move between the cobot and test cell. The original sequence includes an extended wait for the cell-ready signal.',tesla:'Follow a representative pack from fastening to the torque record and end-of-line decision. Compare a variation event with a controlled cycle.',slotting:'Compare reserve replenishment during a wave with filling forward slots before release. Six sample SKUs stand in for the larger model.',layout:'Follow the lift truck and pedestrian paths. The revised layout removes the two crossings shown in this schematic.',npi:'Follow subsystem inputs into separate procedures or a shared calibration, isolation, and qualification sequence.',stretch:'Introduce grip loss or a blocked conveyor and watch the transfer behavior change. These are illustrative fault scenarios.'};
function markup(id){return `<section class="process-simulation" data-simulation="${id}" aria-label="${id} process simulation"><div class="sim-heading"><div><p class="eyebrow">PROCESS SIMULATION</p><h3>See how the system works.</h3></div><span class="sim-chip">ILLUSTRATIVE MODEL</span></div><p class="sim-description">${descriptions[id]}</p><div class="sim-scenarios" role="group" aria-label="Simulation scenario">${options[id].map(([value,label])=>`<button type="button" data-scenario="${value}" aria-pressed="${value===defaultModes[id]}">${label}</button>`).join('')}</div><div class="sim-canvas-scroll" tabindex="0" aria-label="Process diagram, horizontally scrollable on small screens"><canvas width="800" height="450" role="img" aria-label="Animated ${id} process schematic. Use the scenario buttons to compare behavior."></canvas></div><div class="sim-readout"><span class="sim-step">01</span><span class="sim-stage">${stages[id][0]}</span></div><div class="sim-controls"><button type="button" data-action="play">Pause</button><button type="button" data-action="reset">Restart</button><label>Speed <select aria-label="Simulation playback speed"><option value="1">1×</option><option value="2">2×</option><option value=".5">0.5×</option></select></label></div><p class="sim-disclaimer">Simplified sequence; geometry and timing are illustrative. Reported project results are independent of this animation.</p></section>`;}
let caseStop=null;
function controller(element,id,isFacility=false){
const canvas=element.querySelector('canvas'),ctx=canvas.getContext('2d');if(!ctx)return()=>{};
const reduce=root.matchMedia&&root.matchMedia('(prefers-reduced-motion: reduce)').matches;
let state={t:0,conveyorT:0,running:!reduce,speed:1,mode:isFacility?'all':defaultModes[id],blocked:false,plan:false},last=null,frame=0,visible=true,disposed=false,lastStage=-1;
const play=element.querySelector('[data-action="play"]'),select=element.querySelector('select'),events=[];function on(e,type,fn){if(e){e.addEventListener(type,fn);events.push(()=>e.removeEventListener(type,fn));}}
function paint(){if(isFacility)facility(ctx,state.t,state);else{reset(ctx,800,450);renderers[id](ctx,state.t,state.mode);let phase=phaseInfo(id,state.t,state.mode);if(lastStage!==phase.index){lastStage=phase.index;element.querySelector('.sim-step').textContent=String(phase.index+1).padStart(2,'0');element.querySelector('.sim-stage').textContent=phase.label;}}}
function button(){play.textContent=state.running?'Pause':'Play';play.setAttribute('aria-label',state.running?'Pause simulation':'Play simulation');}
function tick(now){if(disposed)return;const dt=last===null?0:Math.min((now-last)/1000,.1);last=now;if(state.running&&visible&&!document.hidden){state.t+=dt*state.speed;if(!state.blocked)state.conveyorT+=dt*state.speed;paint();}frame=root.requestAnimationFrame(tick);}
on(play,'click',()=>{state.running=!state.running;button();});on(element.querySelector('[data-action="reset"]'),'click',()=>{state.t=0;state.conveyorT=0;lastStage=-1;paint();});on(select,'change',()=>{state.speed=Number(select.value);});
element.querySelectorAll('[data-scenario]').forEach(b=>on(b,'click',()=>{state.mode=b.dataset.scenario;state.t=0;lastStage=-1;element.querySelectorAll('[data-scenario]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));paint();}));
if(isFacility){element.querySelectorAll('[data-zone]').forEach(b=>on(b,'click',()=>{state.mode=b.dataset.zone;element.querySelectorAll('[data-zone]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const copy={all:'South-wall inbound → reserve / active → north-wall outbound. VAS in front of the pick tower; Locus beside it.',unload:'Three active Stretch docks on the south wall; four-unit fleet. Cartons transfer to dock conveyors before receiving and putaway.',ecom:'AMR-assisted each pick → Numina / pick tower → pack → carrier sort → parcel ship.',retail:'Case / pallet pick → secondary sort → 9 lanes × 14 positions → LTL trailer. Lane 6 is constrained.'};element.querySelector('.facility-caption').textContent=copy[state.mode];paint();}));on(element.querySelector('[data-action="view"]'),'click',e=>{state.plan=!state.plan;e.currentTarget.textContent=state.plan?'Depth view':'Plan view';e.currentTarget.setAttribute('aria-pressed',String(state.plan));paint();});on(element.querySelector('[data-action="block"]'),'click',e=>{state.blocked=!state.blocked;e.currentTarget.setAttribute('aria-pressed',String(state.blocked));e.currentTarget.textContent=state.blocked?'Clear conveyor':'Block conveyor';paint();});}
let observer;if(root.IntersectionObserver){observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;last=null;},{threshold:0});observer.observe(element);}
button();paint();frame=root.requestAnimationFrame(tick);return()=>{disposed=true;root.cancelAnimationFrame(frame);observer?.disconnect();events.forEach(f=>f());};
}
function mountCase(id,element){destroyCase();if(element)caseStop=controller(element,id);}
function destroyCase(){if(caseStop){caseStop();caseStop=null;}}
function mountFacility(){const e=document.querySelector('.facility-simulation');if(!e)return;controller(e,'facility',true);const dialog=document.querySelector('#layout-dialog'),button=e.querySelector('[data-action="expand"]');if(!dialog||!button)return;let stop;button.addEventListener('click',()=>{dialog.showModal();stop=controller(dialog.querySelector('.facility-simulation'),'facility',true);});dialog.querySelector('[data-action="close-layout"]').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{stop?.();stop=null;button.focus();});dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();});}
// Homepage previews reuse the same sequence and drawing code as the case studies.
function drawPreview(canvas,id,t=0){const c=canvas.getContext('2d');if(!c||!renderers[id])return '';reset(c,800,450);renderers[id](c,t,defaultModes[id]);return phaseInfo(id,t,defaultModes[id]).label;}
root.PortfolioSim={markup,mountCase,destroyCase,mountFacility,drawPreview};
if(typeof module!=='undefined'&&module.exports)module.exports={facility,reset,renderers,phaseInfo,pathPoint,markup,defaultModes,controller};
